fulfill.run:
$utils.setAsBlockRoot($self)

const re = $self.address.entire
const INDEX_KEY = '__DO_NOT_USE_THIS_PROPERTY_index__'
$self.state = $observable({ loading: false, devModeEnabled: null, browserName: 'Chrome', extensionDetailUrl: '', list: [], drawerStatus: '隐藏', currentItem: null })
$self.cleanRow = (row) => {
  if (!row) return row
  const plain = JSON.parse(JSON.stringify(row))
  const c = {}
  Object.keys(plain).forEach((k) => {
    if (k !== INDEX_KEY && !k.endsWith('Display')) c[k] = plain[k]
  })
  return c
}
$self.getScripts = async (filter) => {
  await $chrome.userScripts.configureWorld({ messaging: true })
  return await $chrome.userScripts.getScripts(filter)
}
$self.refreshList = async () => {
  try {
    $self.state.loading = true
    const registered = (await $self.getScripts()) || []
    const registeredIds = registered.map((item) => item.id)
    const record = (await $chrome.storage.local.get()) || {}
    const result = []
    Object.keys(record).forEach((key) => {
      if (key.startsWith('userScriptId_')) {
        const userScript = record[key]
        userScript.enabled = registeredIds.includes(userScript.id)
        result.push(userScript)
      }
    })
    $self.state.list = result
      .sort((a, b) => (b.updateTime || 0) - (a.updateTime || 0))
      .filter((item) => item.id !== '-user-script-isolated' && item.id !== '-user-script-main')
      .map((item) => ({ ...item, updateTimeDisplay: item.updateTime ? $dayjs(item.updateTime).format('YYYY-MM-DD HH:mm:ss') : '', enabledDisplay: item.enabled ? '已启用' : '已停用' }))
  } catch (e) {
    $logger.error('请求用户脚本列表失败', e)
    $message.error('请求用户脚本列表失败')
  } finally {
    $self.state.loading = false
  }
}
$self.saveUserScript = async (userScript) => {
  userScript = $self.cleanRow(userScript)
  const toMatchArr = (arr) => Array.isArray(arr) ? arr.map((m) => (m && typeof m === 'object' ? (m.value != null ? m.value : (m.code != null ? m.code : '')) : m)) : []
  const toJsArr = (arr) => Array.isArray(arr) ? arr.map((b) => ({ code: (b && typeof b === 'object' ? (b.code != null ? b.code : '') : b) || '' })) : []
  userScript = { ...userScript, matches: toMatchArr(userScript.matches), excludeMatches: toMatchArr(userScript.excludeMatches), js: toJsArr(userScript.js) }
  const { name, desc, enabled, updateTime, isBuiltIn, ...registeredUserScript } = userScript
  const storageKey = 'userScriptId_' + userScript.id
  const registeredList = await $self.getScripts({ ids: [userScript.id] })
  const wasRegistered = registeredList && registeredList.length > 0
  await $chrome.storage.local.set({ [storageKey]: { ...userScript, updateTime: Date.now() } })
  try {
    if (wasRegistered) {
      if (userScript.enabled) {
        await $chrome.userScripts.update([registeredUserScript])
      } else {
        await $chrome.userScripts.unregister({ ids: [userScript.id] })
      }
    } else if (userScript.enabled) {
      await $chrome.userScripts.register([registeredUserScript])
    }
  } catch (e) {
    await $chrome.storage.local.remove(storageKey)
    throw e
  }
}
$self.removeUserScript = async (id) => {
  const registeredList = await $self.getScripts({ ids: [id] })
  const wasRegistered = registeredList && registeredList.length > 0
  await $chrome.storage.local.remove('userScriptId_' + id)
  if (wasRegistered) {
    try {
      await $chrome.userScripts.unregister({ ids: [id] })
    } catch (e) {
      $logger.error('注销用户脚本失败', e)
      throw e
    }
  }
}
$self.showDrawer = (row, status) => {
  const dialog = $self.query(re + '.editDrawer').take()
  if (!dialog) return
  $self.state.currentItem = row ? $self.cleanRow(row) : null
  $self.state.drawerStatus = status
  if (status === '新增') {
    dialog.value = { name: '', desc: '', enabled: false, allFrames: false, excludeGlobs: [], includeGlobs: [], matches: [{ value: '*://*/*' }], excludeMatches: [], js: [{ code: '' }], runAt: 'document_idle', world: 'USER_SCRIPT' }
  } else {
    const item = $self.cleanRow(row)
    dialog.value = { ...item, matches: (item.matches || []).map((v) => ({ value: v })), excludeMatches: (item.excludeMatches || []).map((v) => ({ value: v })), js: (item.js || []).map((b) => ({ code: (b && b.code) || '' })) }
  }
  dialog.setPattern(status === '查看' ? 'disabled' : 'editable')
  dialog.setComponentProps({ open: true, title: status + '用户脚本' })
}
$self.dismissDrawer = () => {
  $self.state.drawerStatus = '隐藏'
  $self.state.currentItem = null
  const dialog = $self.query(re + '.editDrawer').take()
  if (dialog) dialog.componentProps.open = false
}
$self.handleSaveDrawer = () => {
  const dialog = $self.query(re + '.editDrawer').take()
  if (!dialog) return
  dialog
    .validate()
    .then(async () => {
      const form = dialog.value || {}
      const matches = (form.matches || []).map((r) => (r && typeof r === 'object' ? r.value : r))
      if (matches.length < 1) {
        $message.error('至少填一个匹配模式')
        return
      }
      if (matches.some((v) => !v || !String(v).trim())) {
        $message.error(matches.length > 1 ? '请输入包含匹配模式或删除当前行' : '请输入包含匹配模式')
        return
      }
      const excludeMatches = (form.excludeMatches || []).map((r) => (r && typeof r === 'object' ? r.value : r))
      if (excludeMatches.some((v) => !v || !String(v).trim())) {
        $message.error('请输入排除匹配模式或删除当前行')
        return
      }
      const jsRows = form.js || []
      if (jsRows.length < 1) {
        $message.error('至少填一个代码块')
        return
      }
      if (jsRows.some((b) => !b || !b.code || !String(b.code).trim())) {
        $message.error(jsRows.length > 1 ? '请输入代码块或删除当前行' : '请输入代码块')
        return
      }
      const js = jsRows.map((b) => ({ code: b.code }))
      const status = $self.state.drawerStatus
      if (status === '新增') {
        try {
          await $self.saveUserScript({ name: form.name, desc: form.desc, enabled: !!form.enabled, allFrames: !!form.allFrames, runAt: form.runAt, world: form.world, matches: matches, excludeMatches: excludeMatches, includeGlobs: [], excludeGlobs: [], js: js, id: $dayjs().format('YYYYMMDDHHmmss'), isBuiltIn: false })
          $message.success('新增用户脚本成功')
          $self.dismissDrawer()
          $self.refreshList()
        } catch (e) {
          $logger.error('新增用户脚本失败', e)
        $message.error('新增用户脚本失败：' + (e && e.message ? e.message : String(e)))
        }
      } else if (status === '编辑') {
        try {
          await $self.saveUserScript({ ...$self.state.currentItem, ...form, matches: matches, excludeMatches: excludeMatches, js: js })
          $message.success('编辑用户脚本成功')
          $self.dismissDrawer()
          $self.refreshList()
        } catch (e) {
          $logger.error('编辑用户脚本失败', e)
        $message.error('编辑用户脚本失败：' + (e && e.message ? e.message : String(e)))
        }
      }
    })
    .catch((e) => $logger.info('校验失败', e))
}
$self.init = async () => {
  try {
    const scheme = navigator.userAgent.includes('Edg/') ? 'edge' : 'chrome'
    $self.state.browserName = scheme === 'edge' ? 'Edge' : 'Chrome'
    const extId = await $chrome.runtime.getId()
    $self.state.extensionDetailUrl = scheme + '://extensions/?id=' + extId
  } catch (e) {
    $logger.error('获取浏览器信息失败', e)
  }
  try {
    await $self.getScripts()
    $self.state.devModeEnabled = true
  } catch (e) {
    $self.state.devModeEnabled = false
  }
  $self.refreshList()
  try {
    $utils.getVipConfig()
  } catch (e) {}
}
$effect(() => { $self.init() }, [])

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$effect(() => {
  $self.display = rf.state.devModeEnabled === false ? 'visible' : 'none'
}, [rf.state.devModeEnabled])
$effect(() => {
  const url = rf.state.extensionDetailUrl
  if (!url) return
  const browserName = rf.state.browserName
  $props({
    description: $React.createElement(
      'span',
      null,
      'chrome.userScripts API 需要在 ' + browserName + ' 扩展管理页中手动开启「允许用户脚本」才能使用。请前往 ',
      $React.createElement('a', { href: url, onClick: (e) => { e.preventDefault(); $chrome.tabs.create({ url: url }) } }, url),
      ' 页面，开启「允许用户脚本」开关后刷新本页。',
      $React.createElement('button', { style: { marginTop: 8, marginLeft: 8, padding: '0 7px', height: 24, fontSize: 14, lineHeight: '22px', color: 'rgba(0, 0, 0, 0.88)', border: '1px solid #d9d9d9', borderRadius: 6, background: '#ffffff', cursor: 'pointer' }, onClick: () => { $chrome.tabs.create({ url: url }) } }, '前往扩展详情页开启')
    ),
  })
}, [rf.state.extensionDetailUrl, rf.state.browserName])

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({
  onClick: async () => {
    const { canceled, result } = await $utils.importJsonFromFile()
    if (canceled || !result) return
    const arr = Array.isArray(result) ? result : [result]
    if (arr.length === 0) {
      $message.error('从文件导入的内容为空')
      return
    }
    for (let i = 0; i < arr.length; i++) {
      const s = arr[i]
      if (!s || !s.id || !s.name || !s.desc || !Array.isArray(s.matches) || s.matches.length === 0 || !Array.isArray(s.js) || s.js.length === 0) {
        $message.error('第 ' + (i + 1) + ' 个用户脚本格式错误，已终止导入')
        return
      }
    }
    try {
      for (const s of arr) {
        await rf.saveUserScript(s)
      }
      await rf.refreshList()
      $message.success('批量导入用户脚本成功，共 ' + arr.length + ' 个')
    } catch (e) {
      $logger.error('批量导入用户脚本失败', e)
      $message.error('批量导入用户脚本失败：' + (e && e.message ? e.message : String(e)))
    }
  },
})

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({
  onClick: async () => {
    const list = rf.state.list || []
    if (list.length === 0) {
      $message.error('没有可导出的用户脚本')
      return
    }
    let extName = '上帝小助手'
    try {
      const manifest = await $chrome.runtime.getManifest()
      extName = (manifest && manifest.name) || extName
    } catch (e) {}
    const data = list.map((item) => ({ ...rf.cleanRow(item), enabled: false }))
    $utils.exportJsonToFile(JSON.stringify(data), extName + '导出用户脚本-' + list.length + '个-' + $dayjs().format('YYYYMMDD_HHmmss') + '.json')
  },
})

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({ onClick: () => rf.showDrawer(null, '新增') })

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $props({ disabled: !!(row && row.isBuiltIn) })
}, [rf.state.list])
$props({
  onConfirm: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    try {
      await rf.removeUserScript(row.id)
      $message.success('删除用户脚本成功')
      rf.refreshList()
    } catch (e) {
      $logger.error('删除用户脚本失败', e)
    $message.error('删除用户脚本失败：' + (e && e.message ? e.message : String(e)))
    }
  },
})

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $props({ disabled: !!(row && row.isBuiltIn) })
}, [rf.state.list])

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const enabled = !!(row && row.enabled)
  $props({
    children: enabled ? '停用' : '启用',
    icon: enabled ? 'MinusCircleOutlined' : 'CheckCircleOutlined',
    type: enabled ? 'default' : 'dashed',
    danger: !enabled,
    onClick: async () => {
      if (!row) return
      try {
        await rf.saveUserScript({ ...row, enabled: !row.enabled })
        row.enabled = !row.enabled
        row.enabledDisplay = row.enabled ? '已启用' : '已停用'
        $message.success(row.enabled ? '启用用户脚本成功' : '停用用户脚本成功')
      } catch (e) {
        $logger.error('saveUserScript 失败', e)
        $message.error((!row.enabled ? '启用用户脚本失败' : '停用用户脚本失败') + '：' + (e && e.message ? e.message : String(e)))
      }
    },
  })
}, [rf.state.list, ($utils.getArrayFieldRow($self, 'ArrayTable') || {}).enabled])

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); if (row) rf.showDrawer(row, '查看') } })

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); if (row) rf.showDrawer(row, '编辑') } })

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    try {
      const newUserScript = { ...rf.cleanRow(row), enabled: false, name: row.name + '-副本', desc: row.desc + '-副本', id: $dayjs().format('YYYYMMDDHHmmss'), isBuiltIn: false }
      await rf.saveUserScript(newUserScript)
      $message.success('复制用户脚本成功')
      await rf.refreshList()
      rf.showDrawer(newUserScript, '编辑')
    } catch (e) {
