const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    let extName = '上帝小助手'
    try {
      const manifest = await $chrome.runtime.getManifest()
      extName = (manifest && manifest.name) || extName
    } catch (e) {}
    $utils.exportJsonToFile(JSON.stringify({ ...rf.cleanRow(row), enabled: false }), extName + '导出用户脚本-' + row.id + '-' + row.name + '-' + $dayjs().format('YYYYMMDD_HHmmss') + '.json')
  },
})

const rf = $utils.getBlockRootField($self)

if (!rf || !rf.state) return

$props({
  onClick: async () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    if (!row) return
    const { canceled, result } = await $utils.importJsonFromFile()
    if (canceled) return
    if (!result || !result.id || !result.name || !result.desc || !result.updateTime || !result.world || !result.runAt || !result.matches || !result.matches.length || !result.js || !result.js.length) {
      $message.error('从文件导入的内容格式错误')
      return
    }
    if (result.id === row.id) {
      try {
        await rf.saveUserScript({ ...result, enabled: false, isBuiltIn: row.isBuiltIn })
        $message.success('从文件导入用户脚本成功')
        rf.refreshList()
      } catch (e) {
        $message.error('从文件导入用户脚本失败')
      }
    } else {
      $modal.confirm({
        title: '从文件导入用户脚本「' + result.name + '」的 id「' + result.id + '」和当前选中的用户脚本「' + row.name + '」的 id「' + row.id + '」不同，确认导入除 id 以外的用户脚本信息吗？',
        okText: '确认',
        onOk: async () => {
          try {
            await rf.saveUserScript({ ...result, enabled: row.enabled, id: row.id, isBuiltIn: row.isBuiltIn })
            $message.success('从文件导入用户脚本成功')
            rf.refreshList()
          } catch (e) {
            $logger.error('从文件导入用户脚本失败', e)
          $message.error('从文件导入用户脚本失败：' + (e && e.message ? e.message : String(e)))
          }
        },
      })
    }
  },
})

const rf = $utils.getBlockRootField($self)

