}, [af && af.value ? af.value.length : 0])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('excludeMatches') + 'excludeMatches'.length)
const af = $self.query(re).take()
$props({
  onClick: () => {
    const result = $utils.getArrayFieldRowAndIndex($self, 'ArrayTable')
    if (af && af.value && result.index != null) {
      af.value = af.value.filter((_, i) => i !== result.index)
    }
  },
})
$effect(() => {
  $self.display = af && af.value && af.value.length >= 1 ? 'visible' : 'none'
}, [af && af.value ? af.value.length : 0])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('js') + 'js'.length)
const af = $self.query(re).take()
$props({
  onClick: () => {
    const result = $utils.getArrayFieldRowAndIndex($self, 'ArrayTable')
    if (af && af.value && result.index != null) {
      af.value = af.value.filter((_, i) => i !== result.index)
    }
  },
})
$effect(() => {
  $self.display = af && af.value && af.value.length >= 1 ? 'visible' : 'none'
}, [af && af.value ? af.value.length : 0])

